for y, hits in zip(years, hits_by_year):
    matches = [h["url"] for h in hits if f"/physics/{y}/press-release" in h["url"]]
    if matches:
        press_urls[y] = matches[0]
print("Discovered names by year:", [(y, d["names"]) for y, d in zip(years, discovered)])
print("Missing press releases:", [y for y in years if y not in press_urls])
