    "type": "object",
    "properties": {"rows": {"type": "array", "items": row_schema}},
    "required": ["rows"],
    "additionalProperties": False
}
print("Budget:", budget())
extraction_prompts = [
    f"Extract every Nobel Prize in Physics laureate for {y} from this official press release. "
