            issues.append((i, row["entity"], c, "missing"))
        elif any(u not in source_text or cell["quote"] not in source_text[u] for u in cell["sources"]):
            issues.append((i, row["entity"], c, "quote/source mismatch"))
print("Rows by year:", [(y, len(r["rows"])) for y, r in zip(years, extracted)])
print("Validation issues:", issues)
print("Nationality and affiliation review:", [
    (r["entity"], r["cells"]["nationality"]["value"], r["cells"]["affiliation_at_award"]["value"])
    for r in candidate_rows
])

